head.script:
scwin.onpageload = function() {
    scwin.data1 = [
        "0", "A", 1, "(주)A", 100,
        "0", "A", 2, "(주)A", 100,
        "0", "A", 3, "*A", 200,
        "0", "B", 1, "*A", 200,
        "0", "B", 2, "A", 200,
        "0", "B", 3, "A", 200,
        "0", "B", 4, "::A", 300,
        "0", "C", 1, "::A", 300,
        "0", "C", 2, "^A", 300,
        "0", "C", 3, "^A", 400,
        "0", "C", 4, "$A", 400
    ];
    dataList1.setData(scwin.data1.slice(0));
}
scwin.grid1_ongroupby = function(options) {
    options.closeGroup = true;
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    //				return false;
    //				return true;
}
scwin.trigger1_onclick = function() {
    var row = dataList1.getTotalRow();
    for (var i = 0; i < row; i++) {
        console.log(i + " ::::: " + dataList1.getCellData(i, 'col3'));
    }
};
scwin.grid1_oncellclick = function(row, col) {
    var value = parseInt(dataList1.getCellData(row, col), 10);
    value++;
    dataList1.setCellData(row, col, value);
}
scwin.formatter = function(data) {
    console.log(data);
};
scwin.search = function() {
    scwin.data1 = [
        "0", "(주)A", 1, "(주)A", 100,
        "0", "A", 2, "(주)A", 100,
        "0", "A", 3, "(주)A", 200,
        "0", "B", 4, "(주)A", 300,
        "0", "C", 5, "*A", 200,
        "0", "A", 6, "*A", 400,
        "0", "B", 7, "*A", 400,
        "0", "C", 8, "*A", 300,
        "0", "A", 9, "::B", 400,
        "0", "B", 10, "::B", 200,
        "0", "C", 11, "::B", 100,
        "0", "A", 12, "A", 100,
        "0", "B", 13, "A", 200,
        "0", "C", 14, "A", 300,
        "0", "A", 15, "B", 400,
        "0", "B", 16, "B", 400,
        "0", "C", 17, "B", 400,
        "0", "A", 18, "cC", 500,
        "0", "B", 19, "Cc", 500,
        "0", "C", 20, "cC", 500,
        "0", "A", 21, "Cc", 400,
        "0", "B", 22, "C", 400,
        "0", "C", 23, "CC", 400,
        "0", "A", 24, "AA", 300,
        "0", "B", 25, "AA", 200,
        "0", "C", 26, "AA", 300,
        "0", "A", 27, "BB", 400,
        "0", "B", 28, "BB", 400,
        "0", "C", 29, "Bb", 300,
        "0", "A", 30, "bB", 300
    ];
    dataList1.setData(scwin.data1.slice(0));
};
scwin.grid1_onchange = function() {
    console.log(JSON.stringify(arguments));
}
scwin.trigger3_onclick = function(e) {
    scwin.search();
};
scwin.grid1_onviewchange = function(info) {
    console.log(JSON.stringify(arguments));
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#grid1_header3', 'drag-n-drop', {
        dx: 0,
        dy: -60
    });
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    // Test step 1.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1.
    //1.
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2grid_head_sort_asc').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    // verify step 2.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2grid_head_sort_asc').length == 1", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //formatter
    //Function unitTest
    //Created By: park
    //Created By: 28-june-2018	
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
